以下是本世界观的“装备特性介绍表”，以JSON格式严格定义：

{
  "装备特性介绍表": {
    "equipment_ranks": [
      {
        "rank_name": "法器",
        "definition": "一到四品的装备只能被称为法器，蕴含微弱灵力，可被修真者以神识初步操控，主要供炼气期、筑基期修士使用。材质为器材。",
        "levels": [
          {
            "level": "一品",
            "features": "灵力波动微弱，功能单一（如单纯的锋利或微弱的法术增幅），勉强可被神识牵引。",
            "suitable_cultivation_level": "炼气初期~后期",
            "examples": ["玄铁飞剑", "聚灵阵盘（微型）", "水纹法袍"]
          },
          {
            "level": "二品",
            "features": "灵力波动稍强，材质略好，操控性提升，能稍微增幅特定属性术法。",
            "suitable_cultivation_level": "筑基初期",
            "examples": ["玄铁精炼剑", "聚灵阵盘（小型）", "涟漪法袍"]
          },
          {
            "level": "三品",
            "features": "灵力较为充盈，材质上乘，操控得心应手，能显著增幅术法威力或附带简单效果（如轻微震慑、加速）。",
            "suitable_cultivation_level": "筑基中期",
            "examples": ["寒光剑", "烈风旗", "金丝内甲"]
          },
          {
            "level": "四品 (半步法宝)",
            "features": "灵力饱满，接近法宝标准，材质为法材中的顶尖，甚至可能在长期温养下诞生一丝微弱灵性雏形，威力远超三品法器。",
            "suitable_cultivation_level": "筑基后期",
            "examples": ["紫电竹剑", "百鬼夜行幡（残缺）", "玄龟盾（仿）"]
          }
        ]
      },
      {
        "rank_name": "法宝",
        "definition": "五到十品的装备可称为法宝，已诞生灵性，能与主人心意相通，威力远超法器，可主动护主，主要供结丹期、元婴期修士使用。材质为宝材。",
        "levels": [
          {
            "level": "五品",
            "features": "灵性初生，略显懵懂，能简单执行主人命令，附带单一属性或简单技能。",
            "suitable_cultivation_level": "结丹初期",
            "examples": ["追风灵剑", "赤焰宝珠", "青木回春幡"]
          },
          {
            "level": "六品",
            "features": "灵性成长，较为聪慧，能更好配合主人，附带的技能威力增强或效果多样化。",
            "suitable_cultivation_level": "结丹中期",
            "examples": ["雷音剑", "玄冰镜", "厚土印"]
          },
          {
            "level": "七品",
            "features": "灵性活跃，几近通透，能自主判断并辅助战斗，附带强大技能或独特神通雏形。",
            "suitable_cultivation_level": "结丹后期",
            "examples": ["七星龙泉剑", "九火神龙罩（仿）", "破空梭"]
          },
          {
            "level": "八品",
            "features": "灵性通透，已生出器灵雏形，威能大增，能独立困敌或发挥奇效。",
            "suitable_cultivation_level": "元婴初期",
            "examples": ["三焰扇", "虚天鼎", "八卦灵盘"]
          },
          {
            "level": "九品",
            "features": "器灵初成，已有简单灵智，能与主人神念交流，神通自成体系。",
            "suitable_cultivation_level": "元婴中期",
            "examples": ["乾坤圈", "太乙五烟罗", "化血神刀"]
          },
          {
            "level": "十品",
            "features": "灵性极高，接近诞生完整器灵，材质为宝材中的极品或掺杂少量灵材，威能强大，能施展出接近灵宝级的神通。是元婴巅峰修士的顶级装备。",
            "suitable_cultivation_level": "元婴后期",
            "examples": ["紫郢剑（仿）", "青索剑（仿）", "混元一气钟"]
          }
        ]
      },
      {
        "rank_name": "灵宝",
        "definition": "十一到十六品的装备被称为灵宝，诞生完整器灵，能与主人配合、辅助修炼，蕴含部分法则之力，威力巨大，主要供化神期和炼虚期修士使用。材质为灵材。基本只存在于灵界。",
        "level_groups": [
          {
            "levels": "十一、十二、十三品",
            "features": "器灵初成（智慧约等于孩童），能执行复杂指令，蕴含一丝法则之力，可初步影响天地元气。",
            "suitable_cultivation_level": "化神期",
            "examples": ["翻山印", "缚妖索", "聚魂幡"]
          },
          {
            "levels": "十四、十五、十六品",
            "features": "器灵成长（智慧约等于少年），配合更为默契，蕴含的法则之力更深厚，神通威力显著提升。",
            "suitable_cultivation_level": "炼虚期",
            "examples": ["覆海珠", "斩魄刀", "九龙神火柱（单柱）"]
          }
        ]
      },
      {
        "rank_name": "通天灵宝",
        "definition": "十七到二十二品的装备被称为通天灵宝，诞生强大器灵，能与主人深度交流、辅助修炼，蕴含完整法则之力，威力极大，主要供合体期和大乘期修士使用。材质为通天灵材。基本只存在于灵界。",
        "level_groups": [
          {
            "levels": "十七、十八、十九品",
            "features": "器灵成熟（智慧堪比成年人，有独特个性），能独立思考并提供战术建议，蕴含浓郁法则之力，一击可改变小范围地貌。",
            "suitable_cultivation_level": "合体期",
            "examples": ["量天尺（仿）", "番天印（仿）", "诛仙四剑阵图（仿，缺剑）"]
          },
          {
            "levels": "二十、二十一、二十二品",
            "features": "器灵强大无比，智慧通达，几乎与主人心意合一，蕴含的法则之力接近圆满，威力深不可测，是大乘期大能的标志性装备。",
            "suitable_cultivation_level": "大乘期",
            "examples": ["太极图（仿）", "盘古幡（仿）", "昊天镜（仿）"]
          }
        ]
      }
    ],
    "special_categories": [
      {
        "category_name": "本命法宝",
        "description": "修士以精血、神魂、本源长期祭炼，与自身大道相合，可随主人修为提升而共同成长，潜力巨大，同阶威力远超普通法宝。通常从五品法宝开始培养。"
      },
      {
        "category_name": "成套法宝",
        "description": "多件法宝组合而成，单独使用威力已然不俗，集齐后可发挥出远超单件总和的恐怖威能，如阵法类法宝。"
      }
    ],
    "growth_notes": "法器基本无成长性。法宝可通过温养和融入少量材料提升，但跨大阶极难。本命法宝成长性较高，可通过融入高级材料、主人修为突破、器灵吞噬同源力量等方式晋升。"
  }
}

